<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class PracticumClass extends Model { protected $fillable=['course_id','laboratory_id','lecturer_id','class_name','room','day','start_time','end_time','capacity','semester','academic_year','is_active']; protected $casts=['is_active'=>'boolean']; public function course(){return $this->belongsTo(Course::class);} public function laboratory(){return $this->belongsTo(Laboratory::class);} public function lecturer(){return $this->belongsTo(User::class,'lecturer_id');} public function registrations(){return $this->hasMany(PracticumRegistration::class);} public function finalRegistrations(){return $this->hasMany(PracticumRegistration::class,'final_class_id');} public function getFilledSeatsAttribute(): int{return $this->finalRegistrations()->where('status','approved')->count();} }
